import hashlib, json, os, sys
out = sys.argv[1]
man = json.load(open('assets/manifest.json'))
webman = json.load(open('assets/manifest.web.json'))
def h(p):
    return hashlib.sha256(open(p,'rb').read()).hexdigest() if os.path.exists(p) else None
recs = {}
for fn in sorted(os.listdir('data/structures')):
    if fn.endswith('.json'):
        d = json.load(open('data/structures/'+fn))
        recs[fn[:-5]] = d.get('archetype') or d.get('recipe')
fam = {}
for sid, arch in recs.items():
    fam.setdefault(arch, []).append(sid)
snap = {'families': {k: sorted(v) for k, v in sorted(fam.items())},
        'assets': {}, 'web_masters': webman['masters'],
        'web_files': {}, 'records': {}}
for k, v in man['assets'].items():
    snap['assets'][k] = {'manifest': v, 'master_sha256': h('assets/gltf/'+k)}
for dirpath, _d, files in os.walk('assets/web'):
    for f in files:
        p = os.path.join(dirpath, f)
        snap['web_files'][os.path.relpath(p, 'assets/web')] = h(p)
for sid in recs:
    snap['records'][sid] = h('data/structures/'+sid+'.json')
json.dump(snap, open(out, 'w'), indent=1, sort_keys=True)
print('assets', len(snap['assets']), 'web_masters', len(snap['web_masters']), 'web_files', len(snap['web_files']))
nul = [k for k, v in snap['assets'].items() if v['master_sha256'] is None]
print('missing masters:', nul)
EOF
